const BASE=new URL('./',self.registration.scope).pathname;const CACHE='awe-faith-shell-v2';const SHELL=['','index.html','styles.css','app.js','manifest.webmanifest','icon.svg','icon-192.png','icon-512.png'].map(p=>BASE+p);self.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(SHELL))));self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE).map(k=>caches.delete(k))))));self.addEventListener('fetch',e=>{const u=new URL(e.request.url);if(u.origin!==location.origin||u.pathname===BASE+'catalog.json')return;e.respondWith(caches.match(e.request).then(hit=>hit||fetch(e.request).then(r=>{const clone=r.clone();caches.open(CACHE).then(c=>c.put(e.request,clone));return r}))) });
